?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;background:transparent;overflow:hidden;font-family:system-ui;color:#fff}.alert{position:fixed;left:50%;top:12%;transform:translate(-50%,-20px) scale(.96);width:min(760px,92vw);padding:20px 24px;border-radius:22px;background:linear-gradient(135deg,rgba(20,27,51,.96),rgba(83,39,122,.94));border:1px solid rgba(255,255,255,.18);box-shadow:0 25px 70px rgba(0,0,0,.4);opacity:0;transition:.45s cubic-bezier(.22,1,.36,1);pointer-events:none}.alert.show{opacity:1;transform:translate(-50%,0) scale(1)}.title{font-size:13px;color:#b9c8ff;margin-bottom:6px}.name{font-size:26px;font-weight:800}.msg{margin-top:8px;font-size:16px;color:#e5ebff}.amount{margin-top:10px;font-size:22px;font-weight:800}.gif{position:absolute;right:15px;top:15px;max-width:110px;max-height:110px;border-radius:12px}</style><div id="a" class="alert"><div id="t" class="title"></div><div id="n" class="name"></div><div id="m" class="msg"></div><div id="v" class="amount"></div></div><script>const slug=<?=json_encode($slug)?>;let last=0;const a=document.getElementById('a'),t=document.getElementById('t'),n=document.getElementById('n'),m=document.getElementById('m'),v=document.getElementById('v');function show(x){t.textContent=<?=json_encode((string)$p['overlay_title'])?>;n.textContent=x.donor_name||'Аноним';m.textContent=x.message||'';v.textContent='+'+Number(x.amount).toFixed(2)+' '+x.currency;a.classList.add('show');setTimeout(()=>a.classList.remove('show'),<?=max(3000,min(30000,(int)$p['overlay_duration']*1000))?>)}async function poll(){try{const r=await fetch('/api/donation_feed.php?s='+encodeURIComponent(slug)+'&after='+last,{cache:'no-store'});const d=await r.json();if(d.ok&&Array.isArray(d.items)){for(const x of d.items){last=Math.max(last,Number(x.id));show(x)}}}catch{}setTimeout(poll,10000)}poll();</script></html>
